pub fn host_convergence_census_standing() -> Rc<HostConvergenceCensus> {
    thread_local! {
        static CACHED: Rc<HostConvergenceCensus> = {
            admit_host_convergence_census(host_convergence_census_rows())
        };
    }
    CACHED.with(|c: &Rc<HostConvergenceCensus>| c.clone())
}

pub fn host_convergence_census_is_admitted() -> bool {
    census_is_well_formed(host_convergence_census_standing())
}

